releases.notes:
1.Add a method for rendering GUI images:
```
RenderJSEvents.onGuiPostRender(event => {
  //Draw an image at a fixed size (Automatic stretching)
    event.drawTextureWithSize("minecraft:textures/item/apple.png", 0, 0, 100, 100, 10)
})
```
2.Fixed the issue of `IGuiRenderHelper.drawString` rendering shadows, now it no longer renders shadows

3.Replaced the event of registering block entity rendering:
old:
```
// in startup scripts
//Errors may occur on the server
ClientEvents.blockEntityRendererRegistry(event => {
    event.register("test:test_block", (c) => RenderJSBlockEntityRenderer
        .create(c)
        .setCustomRender((renderer, context) => {
            var lightLevel = LevelRenderer.getLightColor(context.blockEntity.level, context.blockEntityJS.blockPos.above())
            var poseStack = context.poseStack
            poseStack.pushPose()
            poseStack.translate(0, 5, 0)
            context.renderLevelItem(Items.DIAMOND, poseStack)

            context.scale(-1, -1, 1)
            context.drawTexture("minecraft:textures/item/apple.png", 0, 0, 16, 16)
            poseStack.popPose()



        })
    )
})
```
now:
```
// in client scripts
// support reload
RenderJSEvents.registerBlockEntityRender(event => {
    event.registerOrSwap("test:test_block", (c) => RenderJSBlockEntityRenderer
        .create(c)
        .setCustomRender((renderer, context) => {
            var lightLevel = LevelRenderer.getLightColor(context.blockEntity.level, context.blockEntityJS.blockPos.above())
            var poseStack = context.poseStack
            poseStack.pushPose()
            poseStack.translate(0, 5, 0)
            context.renderLevelItem(Items.DIAMOND, poseStack)

            context.scale(-1, -1, 1)
            context.drawTexture("minecraft:textures/item/apple.png", 0, 0, 16, 16)
            poseStack.popPose()



        })
    )
})
```
